import{_ as s,C as t,o as r,c as o,E as a,a2 as d}from"./chunks/framework.Cc8dJFaW.js";const y=JSON.parse('{"title":"The Code Changed. What Does the Old Approval Recognize?","description":"","frontmatter":{"title":"The Code Changed. What Does the Old Approval Recognize?","article_type":"comparative-study","edition":"research-center","research_question":"可复用审批的实际查找键，是否区分不同请求、目标与代码实现？","summary":"The same tool name need not mean the same implementation, and the same identity string need not bind code content. Comparing pinned AG2 and SIDJUA source with bounded probes separates tool identity, grant lifetime and pause correlation, making the scope of reusable approval inspectable.","sources":["Pinned AG2 source and maintainer tests","Pinned SIDJUA source","2026-11-14 internal isolated experiments"],"date":"2026-11-14","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261114-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-14-sig-20261114-003-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-11-14-sig-20261114-003.md","filePath":"en/engineering/2026-11-14-sig-20261114-003.md","lastUpdated":1794991269000}'),l={name:"en/engineering/2026-11-14-sig-20261114-003.md"};function h(c,e,p,u,g,m){const i=t("ArticleCover"),n=t("ArticleTableScroll");return r(),o("div",null,[a(i,{image:"/assets/covers/daily-2026-11-14-sig-20261114-003-cover.png",kicker:"Research",title:"The Code Changed. What Does the Old Approval Recognize?",summary:"The same tool name need not mean the same implementation, and the same identity string need not bind code content. Comparing pinned AG2 and SIDJUA source with bounded probes separates tool identity, grant lifetime and pause correlation, making the scope of reusable approval inspectable.",version:"2026-11-14",languageHref:"/zh/engineering/2026-11-14-sig-20261114-003",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=d(`<h1 id="the-code-changed-what-does-the-old-approval-recognize" tabindex="-1">The Code Changed. What Does the Old Approval Recognize? <a class="header-anchor" href="#the-code-changed-what-does-the-old-approval-recognize" aria-label="Permalink to &quot;The Code Changed. What Does the Old Approval Recognize?&quot;">​</a></h1><p>Two functions contain different code yet receive the same tool identity string. Keep their module, qualified name and exposed name unchanged, and the identity getter in our isolated probe cannot distinguish them. This is not an authorization incident, but it raises a concrete question: <strong>does an old approval recognize a name, code content or this particular operation? The reuse key determines the answer.</strong> Comparing two implementations with controlled probes helps identify which changes should invalidate an earlier decision.</p><h2 id="three-associations-that-answer-different-questions" tabindex="-1">Three associations that answer different questions <a class="header-anchor" href="#three-associations-that-answer-different-questions" aria-label="Permalink to &quot;Three associations that answer different questions&quot;">​</a></h2><p>Does a human reply answer the right question? Does an earlier grant cover the current operation? Does a resumed execution reconnect to the right waiting request? A single approval interaction can involve three separate identity relations.</p><p>We compare the tool-approval middleware of AG2, an open-source agent application framework, with the pre-action approval lookup in SIDJUA, an agent-operation governance system. They have independent authors and provide primary evidence for their respective implementations. Neither independently reproduces or validates the other&#39;s security. Our probes exercise only an identity getter and a database query.</p><table tabindex="0"><thead><tr><th>Check</th><th>Question it answers</th><th>What it does not establish</th></tr></thead><tbody><tr><td>Human-reply correlation</td><td>Which question received this answer?</td><td>Whether a grant covers different arguments</td></tr><tr><td>Grant-reuse lookup</td><td>Does this call fall within an existing grant?</td><td>Whether the final tool executes or is safe</td></tr><tr><td>Pause/resume correlation</td><td>Which waiting request should continue?</td><td>Whether the grant lookup uses that same request boundary</td></tr></tbody></table><p>This is our analytical distinction, not a shared interface contract of the projects. A reply may be correlated by a parent message ID, and a pause by a request ID in stored metadata. The grant lookup between them still needs its own inspection.</p><h2 id="distinguishing-names-is-not-binding-code-content" tabindex="-1">Distinguishing names is not binding code content <a class="header-anchor" href="#distinguishing-names-is-not-binding-code-content" aria-label="Permalink to &quot;Distinguishing names is not binding code content&quot;">​</a></h2><p>In the pinned <a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/ag2/middleware/builtin/tools/approval.py" target="_blank" rel="noreferrer">AG2 approval middleware</a>, the grant key uses the call event&#39;s source identity, falling back to its name if the source is absent. An “always” answer stores that key in context variables. A later match invokes the continuation without asking again. Arguments may appear in the question shown to the human, but are absent from the reuse key.</p><p>The <a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/ag2/tools/final/function_tool.py" target="_blank" rel="noreferrer">tool identity getter</a> constructs a string from the callable&#39;s module, qualified name and exposed tool name. The registration entry point supplies that source on a copy of the event before middleware execution. Different qualified names can distinguish two functions exposed under the same name. This is not a digest of code content.</p><p>Our internal experiment, executed in the same day&#39;s Analysis, extracted the actual getter from the source AST, removed only its property decorator and invoked it with synthetic owners and callables. The <a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/identity-results.json">identity results</a> retain all three cases. This article reuses that record; Production did not rerun the experiment.</p><table tabindex="0"><thead><tr><th>Changed dimension</th><th>Equal identity strings?</th><th>Bounded observation</th></tr></thead><tbody><tr><td>Same exposed name, different callable qualified name</td><td>No</td><td>These callable identities are separated</td></tr><tr><td>Different function body, same module, qualified name and exposed name</td><td>Yes</td><td>The key does not bind body content</td></tr><tr><td>Same callable, different exposed alias</td><td>No</td><td>The exposed name participates in identity</td></tr></tbody></table><p>The <a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/test/middleware/builtins/test_approval.py" target="_blank" rel="noreferrer">maintainer tests</a> also assert separation of same-name functions, reuse on later turns and reuse after serializing context variables and rebuilding the tool. We read those tests; we did not execute them. Their asserted behavior does not conflict with the three isolated cases: separating qualified names does not establish that arbitrary replacement code invalidates a grant.</p><p>Lifetime is a separate dimension. The <a href="https://raw.githubusercontent.com/ag2ai/ag2/10809bf298ff7c5c5a5c830651070c6f6634f90f/ag2/context.py" target="_blank" rel="noreferrer">human-input context</a> waits for a reply with the matching parent ID, applying a timeout to both sending the question and waiting for the answer. Expiry ends the turn as a human-input error. This limits the wait, not the lifetime of an “always” grant. The approval middleware implements no grant TTL, revocation or argument binding. Disabling “always” ignores existing bypass flags; that switch is not a complete revocation protocol.</p><h2 id="stored-request-identity-is-not-a-lookup-predicate" tabindex="-1">Stored request identity is not a lookup predicate <a class="header-anchor" href="#stored-request-identity-is-not-a-lookup-predicate" aria-label="Permalink to &quot;Stored request identity is not a lookup predicate&quot;">​</a></h2><p>The pinned <a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/approval.ts" target="_blank" rel="noreferrer">SIDJUA approval source</a> stores the request ID in metadata when creating an approval request. Its lookup comment describes request-ID matching and a compatibility fallback, but the executable query never uses that ID. This excerpt preserves the predicates and ordering while omitting returned columns. It is a reformatted source excerpt, not a proposed API.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> approval_queue</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rule_triggered </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pending&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;approved&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;denied&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;now&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ? </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; hours&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>The supplied parameters are agent identity, workflow action pattern and an age window. Target and request ID are not compared by this lookup. The window uses creation time, rather than starting a fresh clock when an approval decision is made.</p><p>The internal experiment executed the exact extracted query in SQLite with explicitly synthetic requests and rows. The <a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/evidence-guide.json">evidence guide</a> and <a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/approval-results.json">query results</a> retain the predicate, controls and rerun instructions. This was not a complete project run that attempted an external operation.</p><table tabindex="0"><thead><tr><th>Control</th><th>Retrieved row or result</th></tr></thead><tbody><tr><td>Original request A</td><td>A&#39;s approved row</td></tr><tr><td>Request B and changed target, other conditions unchanged</td><td>Still A&#39;s approved row</td></tr><tr><td>Changed agent only</td><td>No row</td></tr><tr><td>Changed workflow action pattern only</td><td>No row</td></tr><tr><td>Original row outside the age window</td><td>No row</td></tr><tr><td>Pending row, changed request</td><td>Original pending row</td></tr><tr><td>Denied row, changed request</td><td>Original denied row</td></tr><tr><td>Row changed to an excluded cancelled status</td><td>No row</td></tr><tr><td>Add a newer eligible denied row</td><td>New row wins over the old approval</td></tr></tbody></table><p>There are eight single-row controls and one newest-row control, nine in total. Request and target changes are changes to experimental request metadata; neither is a comparison parameter accepted by the query. The result does not show a complete request validator accepting B. The age case was deliberately far from the cutoff, so exact timestamp-boundary behavior remains untested.</p><p>The <a href="https://raw.githubusercontent.com/GoetzKohlberg/sidjua/747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2/src/pipeline/index.ts" target="_blank" rel="noreferrer">pre-action pipeline</a> shows a different relation: approval PAUSE or BLOCK short-circuits the pipeline, and the separate lookup used to obtain a pending approval ID for a pause does compare the metadata request ID. <strong>Resume bookkeeping can be request-specific while grant reuse follows broader predicates.</strong> An approval-stage pass also continues to budget, classification and policy checks, so finding an approved row is not sufficient for a final operation allowance.</p><h2 id="write-the-reuse-boundary-as-a-falsifiable-contract" tabindex="-1">Write the reuse boundary as a falsifiable contract <a class="header-anchor" href="#write-the-reuse-boundary-as-a-falsifiable-contract" aria-label="Permalink to &quot;Write the reuse boundary as a falsifiable contract&quot;">​</a></h2><p>Our interpretation is that reuse defines a set of calls treated as equivalent for a decision. AG2 primarily groups by a tool identity string and context state; this SIDJUA lookup groups by agent, rule and creation-time window. Whether that scope should be narrow or broad depends on what the approver agreed to, rather than how precise an identifier sounds.</p><p>A counterexample is repeated low-risk work within one workflow. An operator may intentionally authorize many requests at once, and asking again for every occurrence may add friction. Broader reuse is therefore not automatically a vulnerability. The issue is whether the product promise, executable conditions and test expectations agree. If the contract authorizes only target A while the lookup never compares targets, either the implementation or the stated scope needs to change.</p><p>Using an approved request A for target A as the running example, reviewers can collect evidence along this responsibility chain. It is a proposed review method, not a process already shared by both projects.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Input and responsible party</th><th>Required output</th><th>Stop or ask again when</th></tr></thead><tbody><tr><td>Construct operation</td><td>Caller supplies target, arguments and state; trusted entry checks identity</td><td>Attributable operation request</td><td>Identity or preconditions are uncertain</td></tr><tr><td>Present approval</td><td>Interface shows scope; human decides</td><td>Decision with scope and lifetime</td><td>Displayed and actual operations differ</td></tr><tr><td>Store decision</td><td>Authorization storage records scope evidence</td><td>Inspectable grant record</td><td>Record is missing or corrupt</td></tr><tr><td>Look up again</td><td>Authorization layer receives request B for target B</td><td>Match rationale or a new question</td><td>Change exceeds the agreed equivalence relation</td></tr><tr><td>Resume</td><td>Resume layer retrieves waiting request and grant</td><td>Current continue/deny decision</td><td>Request, policy or preconditions changed</td></tr><tr><td>Execute</td><td>Tool boundary rechecks current authority</td><td>Actual effects and result evidence</td><td>Revocation, repeated consumption or isolation violates the contract</td></tr></tbody></table><p>Change one dimension at a time: request ID, target, arguments, body content, policy revision, preconditions, time or restored context. Record whether the design intends reuse or a new question before exercising the real entry point. Matching an existing query is not synonymous with matching user authority. Also inspect one-time consumption, network replay and process, container or operating-system enforcement separately. We did not verify these capabilities; an application-layer allowance cannot establish that they exist.</p><h2 id="evidence-and-unfinished-verification" tabindex="-1">Evidence and unfinished verification <a class="header-anchor" href="#evidence-and-unfinished-verification" aria-label="Permalink to &quot;Evidence and unfinished verification&quot;">​</a></h2><p>Three evidence roles remain separate. Public source supports facts about the pinned implementation. Maintainer tests express the authors&#39; intended assertions. Internal experiments show our execution of an isolated query or function; they are neither independent third-party reproduction nor whole-system security validation. The comparison and review method are our interpretations.</p><p>Sources are pinned to AG2 commit <code>10809bf298ff7c5c5a5c830651070c6f6634f90f</code> and SIDJUA commit <code>747b5bb125c8cc94e7cb99a581dc63bedb2c9bb2</code>, with local source verification on the research date. We do not claim later versions behave identically. AG2ai maintainers provide the middleware, identity and context source and the author-written approval tests; Götz Kohlberg provides the SIDJUA approval and pipeline source. Links above identify the relevant file at its pinned revision. Publication or citation status adds no validation strength.</p><p>The internal SQL probe used SQLite 3.53.3 with Node 24.19.0; the identity probe used Python 3.12.9. The proposed public <a href="/joinwell52/assets/evidence/2026-11-14-sig-20261114-003/evidence-index.json">evidence index</a> preserves results, source checksums, environment and synthetic controls, declaring its redactions. It is an attachment prepared for this candidate, not a claim that the article has been released.</p><p>No complete approval middleware, real human interaction, context restoration, transport merge, matcher, condition parser, decision writer, resume-token verifier or external tool was executed. We measured no real side effect and established no attacker control of identities. Reading a variable-filtering function does not audit all transport entry points. Framework-wide exploitability, revocation guarantees, concurrent one-time consumption and operating-system isolation remain outside this evidence.</p><p>The next step is to establish maintainer intent, then use trusted request construction and actual resume entry points to check changed requests and targets, old decisions after code updates, propagation of denials and expiry, and effects of repeated calls. <strong>Until then, the supported finding is the boundary of two reuse keys, rather than a verdict on whole-system security.</strong></p>`,34))])}const b=s(l,[["render",h]]);export{y as __pageData,b as default};
